 for(const b of engine.bullets){c.strokeStyle=b.id==='rifle'?'#fff4c0':'#eecb77';c.lineWidth=2;c.beginPath();c.moveTo(b.x,b.y);c.lineTo(b.x-b.vx*.014,b.y-b.vy*.014);c.stroke();}
 for(const a of engine.particles){c.globalAlpha=clamp(a.life/.6,0,1);c.fillStyle=a.color;c.fillRect(Math.round(a.x),Math.round(a.y),a.size,a.size);}c.globalAlpha=1;
 for(const a of engine.effects)this.text(a.text,a.x,a.y-(.8-a.t)*26,a.color,15);
 const near=engine.nearestObject();if(near&&!engine.paused){c.strokeStyle='#f0d084';c.lineWidth=1.5;c.globalAlpha=.8+.2*Math.sin(this.time*4);c.beginPath();c.ellipse(near.x,near.y+3,near.type==='plot'?22:28,10,0,0,Math.PI*2);c.stroke();c.globalAlpha=1;}
