 drawNight(engine){const c=this.ctx,s=engine.s,p=s.player;const minute=s.minute,night=minute>1110?Math.min(.5,(minute-1110)/400):minute<360?.42:0;if(night){c.fillStyle=`rgba(13,27,54,${night})`;c.fillRect(0,0,WORLD.w,WORLD.h);if(!['farm','market'].includes(s.region)){c.save();c.fillStyle='#07122577';c.beginPath();c.rect(0,0,WORLD.w,WORLD.h);c.arc(p.x,p.y-18,engine.qty('flashlight')?265:135,0,Math.PI*2);c.fill('evenodd');c.restore();}if(engine.qty('flashlight')){const light=c.createRadialGradient(p.x,p.y-18,10,p.x,p.y-18,150);light.addColorStop(0,'#fff3cb35');light.addColorStop(1,'#fff3cb00');c.fillStyle=light;c.fillRect(p.x-150,p.y-168,300,300);}if(s.region==='farm'){const g=c.createRadialGradient(1010,466,0,1010,466,150);g.addColorStop(0,'#f4c98144');g.addColorStop(1,'#f4c98100');c.fillStyle=g;c.fillRect(860,316,300,300);}}}
